  "Quando l'ufficio ti affida un mezzo, lo trovi qui con i suoi documenti. Per un attrezzo con l'etichetta QR, tocca «Scansiona».": "Quand le bureau te confie un véhicule, tu le trouves ici avec ses documents. Pour un outil avec l'étiquette QR, touche «Scanner».",
  "Quando prendi materiale dall’Inventario, la richiesta compare qui con la risposta del magazzino.": "Quand tu prends du matériel dans l'Inventaire, la demande apparaît ici avec la réponse du magasin.",
