  "Prepara il verbale dalla commessa → Cantiere → Collaudo e consegna: verifiche, esito, riserve, responsabili e documenti consegnati. Il collegamento alla firma elettronica è ancora da completare: non inviare una richiesta basata sul solo titolo.": "Prépare le procès-verbal depuis le dossier → Chantier → Réception et livraison : vérifications, résultat, réserves, responsables et documents remis. Le lien avec la signature électronique n’est pas encore terminé : n’envoie pas une demande basée seulement sur le titre.",
