  "Materiali consegnati non disponibili. Puoi usare gli articoli o aggiungere una voce libera; le scelte già fatte restano salvate nel modulo.": "Matériaux livrés non disponibles. Tu peux utiliser les articles ou ajouter une ligne libre ; les choix déjà faits restent enregistrés dans le formulaire.",
