  "Documento da mostrare al cliente prima della firma. Non è il normale riepilogo di fine giornata.": "Document à montrer au client avant la signature. Ce n’est pas le résumé normal de fin de journée.",
  "Verifico cantiere e rapporti già inviati…": "Je vérifie le chantier et les rapports déjà envoyés…",
  "Non riesco a svuotare la bozza sul telefono.": "Je n’arrive pas à vider le brouillon sur le téléphone.",
  "Non riesco a verificare i rapporti o il tuo ruolo. I dati inseriti restano qui; l’invio è sospeso per evitare doppioni.": "Je n’arrive pas à vérifier les rapports ou ton rôle. Les données saisies restent ici ; l’envoi est suspendu pour éviter les doublons.",
  "Riprova la verifica": "Relancer la vérification",
  "La conferma del cliente è gestita dal capocantiere. Per raccontare la tua giornata torna al rapportino giornaliero.": "La confirmation du client est gérée par le chef de chantier. Pour raconter ta journée, retourne au rapport du jour.",
  "In questa azienda il giornaliero lo invia il responsabile. Tu registra entrata e uscita; puoi aggiungere foto e segnalare problemi dal cantiere.": "Dans cette entreprise, le rapport du jour est envoyé par le responsable. Toi, pointe l’entrée et la sortie ; tu peux ajouter des photos et signaler des problèmes depuis le chantier.",
  "I dati compilati restano visibili, ma non vengono spostati a oggi.": "Les données remplies restent visibles, mais ne sont pas déplacées à aujourd’hui.",
  "Motivo: {motivo}": "Motif : {motivo}",
  "Per separare i due documenti nello stesso giorno occorre aggiornare il database: non sostituiamo quello già inviato.": "Pour séparer les deux documents le même jour, il faut mettre à jour la base de données : nous ne remplaçons pas celui déjà envoyé.",
  "{data} — non inviabile": "{data} — envoi impossible",
  "Correzione richiesta dall’ufficio: puoi rimandarla anche dopo la scadenza originale.": "Correction demandée par le bureau : tu peux la renvoyer même après l’échéance d’origine.",
