  "Giornata fuori termine.": "Journée hors délai.",
  "Qui segni solo le tue ore. Il racconto del cantiere, le foto e i materiali li scrive il capocantiere.": "Ici tu notes seulement tes heures. Le récit du chantier, les photos et les matériaux, c’est le chef de chantier qui les écrit.",
