  "I dati salvati sono cambiati. Mantengo gli aggiornamenti su altri campi; scegli come risolvere eventuali differenze. La verifica d’ordine andrà riconfermata.": "Les données enregistrées ont changé. Je garde les mises à jour sur les autres champs ; choisis comment régler les différences. La vérification de commande devra être reconfirmée.",
