  "Verifica tecnica": "Vérification technique",
  "Colore non riconosciuto: rappresentazione neutra; fa fede il codice scritto.": "Couleur non reconnue : représentation neutre ; c’est le code écrit qui fait foi.",
  "Misure finite verificate · non è un ordine": "Mesures finies vérifiées · ce n’est pas une commande",
  "Misura del foro · non d’ordine": "Mesure de la baie · pas pour la commande",
